with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'テンペスタ（嵐）', 'ジョルジョーネ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/Giorgione_-_Das_Gewitter.jpg/960px-Giorgione_-_Das_Gewitter.jpg', 'ヴェネツィアの画家ジョルジョーネが1508年頃に描いた油彩画で、貴族ガブリエーレ・ヴェンドラミンの依頼とされます。稲妻の走る空の下、左に立つ男と、右で赤子に乳を与える女が描かれていますが、主題を記した当時の記録はなく、聖書や神話、寓意など多くの解釈が出されてきました。X線調査では、男の位置にもともと裸婦が描かれていたことがわかっています。人物より風景と大気が主役ともいえる画面は、風景画の発展を先取りした作品とされます。ヴェネツィアのアカデミア美術館所蔵。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Giorgione_-_Das_Gewitter.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 1
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('ポーラ美術館、ゴンザレス＝トレス代表作を収蔵', '《「無題」（パーフェクト・ラヴァーズ）》を新収蔵。12月4日から開催中のモネ展で公開。', '神奈川県箱根町のポーラ美術館が、キューバ出身の作家フェリックス・ゴンザレス＝トレス（1957〜96年）の代表作《「無題」（パーフェクト・ラヴァーズ）》（1987〜1990年）を新たに収蔵した。同じ形の壁掛け時計2つを同じ時刻に合わせて並べた作品で、時計はやがて時間がずれ、いずれ片方が先に止まる。1980年代のエイズ危機の時期に制作され、作家と恋人との関係が反映されている。12月4日から、開催中の「モネ没後100年・開館25周年記念 あたらしい目―モネと21世紀のアート」（2027年4月7日まで）で公開される。', '', '美術館', 'https://bijutsutecho.com/magazine/news/headline/33354',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('嵯峨嵐山文華館、2027年の4展を発表', '竹久夢二、はしもとみお、福田美術館共催の名画祭、百人一首展の4展を予定。', '京都市右京区の嵯峨嵐山文華館が、2027年に予定する4つの展覧会を発表した。「いちからわかる竹久夢二」（2027年3月17日～7月11日）では日本画に加え油彩画や装幀、千代紙なども紹介し、水彩画の連作《長崎十二景》《女十題》も公開する。続いて木彫作家の「はしもとみお展（仮）」（7月17日～8月29日）、福田美術館と共催の「オールスター名画祭 ―でっかい、ながーい!? すっごい絵―（仮）」（9月11日～2028年1月16日）、小倉百人一首にまつわる作品を集めた「百人一首展（仮）」（2028年1月29日～7月2日）を開催する。', '', '展覧会', 'https://artexhibition.jp/topics/news/20261106-AEJ3035827/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('安藤忠雄ともの派の展覧会、ヴェネチアで', 'プンタ・デラ・ドガーナで2027年3月21日から。安藤の建築写真ともの派作品が対話。', 'イタリア・ヴェネチアのプンタ・デラ・ドガーナで、展覧会「Tadao Ando & Mono-ha. The Five Elements」が2027年3月21日から11月21日まで開催される。安藤忠雄が自ら撮影した、初公開を含む数百点の建築写真と、ピノー・コレクション所蔵のもの派の作品を組み合わせ、両者の共通点を探る。構成は「空気」「土」「水」「火」「コンクリート」の5つの元素に基づく。会場は安藤が歴史的建造物を改修し2009年に開館した美術館で、安藤はコレクターのフランソワ・ピノーと25年以上協働している。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33351',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('エドワード・ゴーリー展、静岡市美術館で', '11月28日から。日本初公開を含む原画やポスターなど約300点で「秘密のメッセージ」を読み解く。', '静岡市美術館で「エドワード・ゴーリー 秘密のメッセージ」が2026年11月28日から2027年1月11日まで開催される。絵本作家エドワード・ゴーリー（1925-2000）の作品に込められた「秘密のメッセージ」を、絵本や挿絵の原画、ポスター、出版物など、日本初公開を含む約300点から読み解く。自ら文章と絵を手がけた「主著」を日本文化の影響などの視点から紹介するほか、他の作家の書籍への挿絵やブックデザイン、バレエ好きだったゴーリーの舞台芸術の仕事にも焦点を当てる。', '', '展覧会', 'https://artexhibition.jp/topics/news/20261112-AEJ3039675/',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('最後の晩餐', 'The Last Supper', 'レオナルド・ダ・ヴィンチ', 'Leonardo da Vinci',
        1498,
        (select slug from public.art_movements where slug = 'renaissance'),
        'サンタ・マリア・デッレ・グラツィエ修道院', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Leonardo_da_Vinci_%281452-1519%29_-_The_Last_Supper_%281495-1498%29.jpg/960px-Leonardo_da_Vinci_%281452-1519%29_-_The_Last_Supper_%281495-1498%29.jpg', 'ミラノ公ルドヴィーコ・スフォルツァの依頼で、サンタ・マリア・デッレ・グラツィエ修道院の食堂の壁に1495〜98年頃に描かれた、約4.2×9.1mの壁画です。イエスが「この中の一人が私を裏切る」と告げた瞬間の使徒たちの動揺を、3人ずつ4つのまとまりで表し、一点透視図法の消失点をイエスの頭部に置いて視線を中心へ導いています。乾いた漆喰にテンペラで描いたため早くから傷み、1999年に20年以上に及ぶ修復が完了しました。それまでの「最後の晩餐」図ではユダだけを食卓の手前に離して座らせるのが通例でしたが、レオナルドは全員を同じ側に並べ、身ぶりと表情によって心の動きを描き分けました。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Leonardo_da_Vinci_(1452-1519)_-_The_Last_Supper_(1495-1498).jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('ブレダの開城', 'The Surrender of Breda', 'ディエゴ・ベラスケス', 'Diego Velázquez',
        1635,
        (select slug from public.art_movements where slug = 'baroque'),
        'プラド美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Velazquez-The_Surrender_of_Breda.jpg/960px-Velazquez-The_Surrender_of_Breda.jpg', 'フェリペ4世の軍の勝利を記念する12点の戦勝画の一つとして、マドリードのブエン・レティーロ宮殿「諸王国の間」のために1634〜35年に描かれた、縦3m余りの大作です。1625年にオランダの要塞都市ブレダが開城した3日後、敗将ユスティヌス・ファン・ナッサウがスペイン軍の将軍スピノラに町の鍵を渡す場面で、鍵が構図全体の軸として画面中央に据えられています。右側に林立する槍から「ラス・ランサス（槍）」の通称でも呼ばれます。戦闘の激しさや勝者の誇示ではなく、敗者を丁重に迎える勝者の寛容と敵味方の和解に焦点を当てた点が、バロックの戦勝画のなかでも際立っています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Velazquez-The_Surrender_of_Breda.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('東海道五拾三次之内 蒲原 夜之雪', 'Evening Snow at Kambara (number sixteen of the series Fifty-three Stations of the Tokaido)', '歌川広重', 'Utagawa Hiroshige',
        1833,
        (select slug from public.art_movements where slug = 'ukiyo-e'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1985.317/1985.317_web.jpg', '江戸から京都までの宿場を描いた保永堂版「東海道五拾三次」の16番目の図で、駿河の宿場・蒲原の夜を描いています。降りしきる雪が家並みと山を白く覆い、雪の中を行く人々の姿が寒さと静けさを伝えます。降る雪は版木を彫りくぼめて紙の白を残すことで表され、木版画ならではの表現になっています。シリーズは「近年の大当たり」と評されるほどの人気を呼びました。北斎の「冨嶽三十六景」などで広まった名所風景版画を受け継ぎつつ、名所や名物よりも季節・天候・時刻がかもす情緒を主題とした点に、広重の新しさがよく表れた一図です。クリーブランド美術館所蔵の一枚は1833年の作とされます。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1985.317')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('浦上玉堂', 'Uragami Gyokudō', '玉堂',
        1745, 1820, 'japan', array['nanga']::text[],
        '武士の身分を捨て、七絃琴と絵を友に諸国を旅した江戸時代後期の文人画家。', '備中国（いまの岡山県）の鴨方藩に仕える武士の家に生まれました。35歳のころ「玉堂清韻」の銘がある中国伝来の七絃琴を手に入れ、「玉堂琴士」と号しました。本人は画家よりも琴を弾く者であることを自負していたともいわれます。

50歳のとき武士の身分を捨てて脱藩し、二人の息子、春琴と秋琴を連れて江戸、京都、大坂、信濃などを旅して暮らしました。描いたのは主に墨による山水画で、構図や筆づかいの種類は多くないものの、同じ主題をくり返し描くなかで水墨の表現を深め、中国の文人画の本質に迫ったと評価されています。

佳作は60歳を過ぎてからのものが多いとされます。代表作の「東雲篩雪図」は国宝に指定され、作家・川端康成が愛蔵したことでも知られています。息子の浦上春琴も文人画家として活躍しました。', 'https://ja.wikipedia.org/wiki/%E6%B5%A6%E4%B8%8A%E7%8E%89%E5%A0%82')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('アンドレ・ドラン', 'André Derain', 'ドラン',
        1880, 1954, 'west', array['fauvism']::text[],
        'マティスとともにフォーヴィスムを切り開き、のちに古典的な表現へ向かったフランスの画家。', 'パリ近郊のシャトゥーに生まれました。エンジニアの勉強をしながら画家ウジェーヌ・カリエールのもとで絵を学び、そのころマティスと知り合います。1900年にはヴラマンクと出会い、シャトゥーに共同のアトリエを構えました。

1905年の夏、南仏の港町コリウールでマティスとともに制作し、強い原色を大胆に置く画風を確立しました。同じ年のサロン・ドートンヌで彼らの作品が集められた部屋は批評家に「野獣の檻」と呼ばれ、フォーヴィスム（野獣派）の名の由来となります。画商ヴォラールの勧めで1905年末から翌年にかけてロンドンに滞在し、テムズ川沿いの風景を鮮やかな色彩で描いた連作も知られています。

1907年ごろからはピカソら「洗濯船」の画家たちと交わり、1921年のイタリア旅行をきっかけに古典的な表現へと向かいました。第二次世界大戦中の1941年にドイツを訪れたことから戦後は対独協力者とみなされ、1954年に自動車事故で亡くなりました。代表作に「コリウールの山々」「チャリング・クロス橋」があります。', 'https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%B3%E3%83%89%E3%83%AC%E3%83%BB%E3%83%89%E3%83%A9%E3%83%B3')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('フアン・グリス', 'Juan Gris', 'グリス',
        1887, 1927, 'west', array['cubism']::text[],
        'ピカソ、ブラックに続いてキュビスムを独自に推し進めた、パリで活動したスペイン出身の画家。', '本名はホセ・ビクトリアーノ・ゴンサレス＝ペレスといい、マドリードに生まれました。地元の学校で工学を学んだのち絵の道に進み、1905年からフアン・グリスと名乗ります。1906年にパリへ移り、モンマルトルの集合アトリエ「洗濯船」に住んで、新聞や雑誌の風刺画で生計を立てました。

近くに住んでいたピカソとブラックから大きな影響を受け、1911年ごろから本格的に油彩に取り組みました。1912年にはアンデパンダン展に初めて出品し、ピカソの肖像も描いています。同じ年、画商カーンワイラーと専属契約を結びました。1913年以降は紙を貼りつけるパピエ・コレも多用し、形を組み立て直す総合的キュビスムの代表的な画家となりました。明快な色面と幾何学的な構成が特徴です。

1924年にはディアギレフのバレエ・リュスのために舞台装置と衣装を手がけました。1927年、腎臓の病のため40歳で亡くなりました。代表作に「パブロ・ピカソの肖像」「チェックのテーブルクロスのある静物」があります。', 'https://ja.wikipedia.org/wiki/%E3%83%95%E3%82%A2%E3%83%B3%E3%83%BB%E3%82%B0%E3%83%AA%E3%82%B9')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
